  const frac = i % 4 === 0;                       // every 4th cart uses non-integer prices
  const items = Array.from({ length: len }, () => ({
    price: frac ? Math.round(rnd() * 1e6) / 100 : Math.floor(rnd() * 100000),
    qty: 1 + Math.floor(rnd() * 20),
  }));
  for (const [a, b] of [[oldTotal(items, 0), newTotal(items, 0)], [oldTotal(items), newTotal(items)]]) {
    n++; if (!Object.is(a, b)) { diff++; if (diff < 5) console.log('DIFF', JSON.stringify(items), a, b); }
  }
}
console.log(`discount 0: compared ${n} totals, differences: ${diff}`);

// Informational: new total vs exact integer arithmetic (integer subtotal, whole-percent discount).
let m = 0, mism = 0, ties = 0;
for (let sub = 0; sub <= 20000; sub += 7) for (let d = 0; d <= 100; d += 5) for (const bulk of [0, 5]) {
  const num = BigInt(sub) * BigInt(100 - d) * BigInt(100 - bulk);        // exact value * 10000
  const q = num / 10000n, r = num % 10000n;
  if (r === 5000n) { ties++; continue; }                                  // .5 ties: rounding rule not specified
  const exact = Number(r > 5000n ? q + 1n : q);
  const items = bulk ? Array.from({ length: 10 }, (_, k) => ({ price: k === 0 ? sub : 0, qty: 1 })) : [{ price: sub, qty: 1 }];
  m++; if (newTotal(items, d / 100) !== exact) { mism++; if (mism < 5) console.log('MISMATCH', sub, d, bulk, newTotal(items, d / 100), exact); }
